import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.*;

public class ReportExportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private static final String EXPORT_DIR = "/var/reports/staging";

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String templateName = req.getParameter("template");

        if (reportId == null || format == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate format is one of allowed types
        if (!Arrays.asList("csv", "json", "xml").contains(format)) {
            resp.sendError(400, "Invalid format");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Fetch report metadata
            String metaQuery = "SELECT title, owner, created_at, query_template FROM reports WHERE report_id = ?";
            PreparedStatement metaStmt = conn.prepareStatement(metaQuery);
            metaStmt.setString(1, reportId);
            ResultSet metaRs = metaStmt.executeQuery();

            if (!metaRs.next()) {
                resp.sendError(404, "Report not found");
                return;
            }

            String title = metaRs.getString("title");
            String queryTemplate = metaRs.getString("query_template");

            // Build dynamic query from template with user-supplied parameters
            Map<String, String> params = new HashMap<>();
            Enumeration<String> paramNames = req.getParameterNames();
            while (paramNames.hasMoreElements()) {
                String name = paramNames.nextElement();
                if (!name.equals("id") && !name.equals("format") && !name.equals("template")) {
                    params.put(name, req.getParameter(name));
                }
            }

            // StringSubstitutor replaces ${varName} placeholders in the query template
            StringSubstitutor sub = new StringSubstitutor(params);
            String finalQuery = sub.replace(queryTemplate);

            // Execute the constructed query
            Statement dataStmt = conn.createStatement();
            ResultSet dataRs = dataStmt.executeQuery(finalQuery);

            // Write results to staging file
            String filename = title.replaceAll("[^a-zA-Z0-9_-]", "_") + "." + format;
            File outputFile = new File(EXPORT_DIR, filename);

            try (PrintWriter writer = new PrintWriter(new FileWriter(outputFile))) {
                ResultSetMetaData rsMeta = dataRs.getMetaData();
                int colCount = rsMeta.getColumnCount();

                if ("csv".equals(format)) {
                    // Write CSV header
                    for (int i = 1; i <= colCount; i++) {
                        writer.print(rsMeta.getColumnName(i));
                        if (i < colCount) writer.print(",");
                    }
                    writer.println();
                    while (dataRs.next()) {
                        for (int i = 1; i <= colCount; i++) {
                            writer.print(dataRs.getString(i));
                            if (i < colCount) writer.print(",");
                        }
                        writer.println();
                    }
                } else if ("json".equals(format)) {
                    writer.println("[");
                    boolean first = true;
                    while (dataRs.next()) {
                        if (!first) writer.println(",");
                        writer.print("  {");
                        for (int i = 1; i <= colCount; i++) {
                            writer.printf("\"%s\":\"%s\"", rsMeta.getColumnName(i), dataRs.getString(i));
                            if (i < colCount) writer.print(",");
                        }
                        writer.print("}");
                        first = false;
                    }
                    writer.println("\n]");
                }
            }

            // Return file path for async download
            resp.setContentType("application/json");
            resp.getWriter().printf("{\"status\":\"ready\",\"path\":\"%s\"}", outputFile.getName());

        } catch (SQLException e) {
            resp.sendError(500, "Database error: " + e.getMessage());
        }
    }
}
